const crypto = require("crypto");

// ── HMAC-SHA256 Checksum ─────────────────────────────────
function generateSignature(dataString, key) {
  return new Promise((resolve, reject) => {
    crypto.randomBytes(4, (err, buf) => {
      if (err) { reject(err); return; }
      const salt        = buf.toString("hex");
      const finalString = dataString + "|" + salt;
      const hash        = crypto.createHmac("SHA256", key).update(finalString).digest("hex");
      resolve(hash + "####" + salt);
    });
  });
}

// ── Config ───────────────────────────────────────────────
const MERCHANT_KEY = "w%_56GvUg70GhNsj";
const MID          = "BLAXSZ43231808043698";
const custId       = "CUST_" + 
$('WhatsApp Trigger').first().json.contacts[0].wa_id;
// ── Build Body ───────────────────────────────────────────
const orderId = "TORI_" + Date.now();

const body = {
  requestType : "Payment",
  mid         : MID,
  websiteName : "WEBSTAGING",
  orderId     : orderId,
  txnAmount   : { value: "20.00", currency: "INR" },
  userInfo    : { custId: custId },
  // callbackUrl : `https://secure.paytmpayments.com/theia/paytmCallback?orderId=${orderId}`
};

// ── Sign the exact body string ───────────────────────────
const bodyString = JSON.stringify(body);   // ← this exact string gets signed
const signature  = await generateSignature(bodyString, MERCHANT_KEY);

// ✅ Build the COMPLETE http body as a string HERE
// so n8n doesn't touch or re-serialize it
const httpBody = `{"body":${bodyString},"head":{"signature":"${signature}"}}`;

// ── Return ───────────────────────────────────────────────
return [{
  json: {
    orderId,
    signature,
    httpBody,   // ← send this directly — do NOT use JSON.stringify again
    DEBUG_bodyString : bodyString,    // ← check this is correct
    DEBUG_signedWith : MERCHANT_KEY   // ← confirm correct key
  }
}];

