const crypto = require("crypto");

const MERCHANT_KEY = "F_MzmwLh6KQuq9i0";

// ── Get data from Paytm callback (webhook body) ──────────
const callbackData = $input.first().json;

// Paytm sends checksum in "head.signature" for JSON callback
const receivedSignature = callbackData.head?.signature;
const body              = callbackData.body;

if (!receivedSignature) {
  throw new Error("No signature found in callback");
}

// ── Recreate the string Paytm signed ────────────────────
const bodyString = JSON.stringify(body);

// ── Split checksum into hash + salt ─────────────────────
const parts = receivedSignature.split("####");
if (parts.length !== 2) {
  throw new Error("Invalid checksum format");
}

const [receivedHash, salt] = parts;

// ── Recompute hash using same algo ──────────────────────
const finalString  = bodyString + "|" + salt;
const computedHash = crypto
  .createHmac("SHA256", MERCHANT_KEY)
  .update(finalString)
  .digest("hex");

// ── Compare ─────────────────────────────────────────────
const isValid = computedHash === receivedHash;

if (!isValid) {
  throw new Error("❌ Checksum mismatch — possible tampering!");
}

// ── Return validated data to next node ──────────────────
return [{
  json: {
    checksumValid  : true,
    orderId        : body.orderId,
    txnStatus      : body.resultInfo?.resultStatus,   // "TXN_SUCCESS" / "TXN_FAILURE"
    txnId          : body.txnId,
    txnAmount      : body.txnAmount,
    resultCode     : body.resultInfo?.resultCode,
    resultMsg      : body.resultInfo?.resultMsg,
    rawBody        : body
  }
}];

