}];

// 🚀 FIX 1: Update function to return BOTH the shifted Date and Time
function convertISTtoUTC(dateStr, timeStr) {
    const istOffset = '+05:30';

    // Check input validity
    if (!dateStr || !/^\d{4}-\d{2}-\d{2}$/.test(dateStr)) {
        throw new Error(`Invalid date string: "${dateStr}"`);
    }
    if (!timeStr) {
        throw new Error(`Missing time string`);
    }

    // Normalize timeStr to HH:MM:SS for ISO
    let timePart = timeStr.trim();
    if (/^\d{2}:\d{2}:\d{2}$/.test(timePart)) {
        // Already contains seconds
    } else if (/^\d{2}:\d{2}$/.test(timePart)) {
        timePart += ':00';
    } else if (/^\d{2}$/.test(timePart)) {
        timePart += ':00:00';
    } else {
        throw new Error(`Invalid time format: "${timeStr}"`);
    }

    // Create actual Date object enforcing IST timezone explicitly
    const isoString = `${dateStr}T${timePart}${istOffset}`;
    const dateObj = new Date(isoString);

    if (isNaN(dateObj.getTime())) {
        throw new Error(`Invalid time value: "${isoString}"`);
    }

    // Return both the UTC Date (to handle midnight day-shifts) and UTC Time
    return {
        utcDate: dateObj.toISOString().substring(0, 10), // Returns YYYY-MM-DD
        utcTime: dateObj.toISOString().substring(11, 19) // Returns HH:MM:SS
    };
}

// Extract properties from input JSON data context
const { appointmentData } = $input.first().json;

// Extract date and time from WhatsApp trigger
const whatsappId = $('Get booking details from beforepaymentbookingdetails').first().json.booking_date;
const bookingref = $('Payment Webhook').first().json.body.payload.payment_link.entity.reference_id;

const [dateFromWhatsApp, timeFromWhatsApp] = whatsappId.split('_');

let startTime = "09:00"; // Default fallback initialization
let endTime = "10:00";

if (timeFromWhatsApp) {
    // Robust AM/PM Extraction and Normalization Rule
    let rawTimeStr = timeFromWhatsApp.trim().toUpperCase();

    // Try to isolate numerical structures and AM/PM strings (e.g. "800AM" -> hrs: 8, mins: 0, period: AM)
    const amPmMatch = rawTimeStr.match(/^(\d{1,2}):?(\d{2})?\s*(AM|PM)$/);

    if (amPmMatch) {
        let hours = parseInt(amPmMatch[1], 10);
        let minutes = amPmMatch[2] ? amPmMatch[2] : "00";
        let period = amPmMatch[3];

        if (period === 'PM' && hours !== 12) hours += 12;
        if (period === 'AM' && hours === 12) hours = 0;

        startTime = `${String(hours).padStart(2, '0')}:${minutes}`;

        let endHours = hours + 1;
        endTime = `${String(endHours).padStart(2, '0')}:${minutes}`;
    } 
    // Standard clean 24-hour string lookup fallback handler ("18:00")
    else if (rawTimeStr.includes(':')) {
        startTime = rawTimeStr;
        const [hours, minutes] = startTime.split(':');
        const endTimeHours = String(parseInt(hours, 10) + 1).padStart(2, '0');
        endTime = `${endTimeHours}:${minutes}`;
    } 
    // Clean integer-only fallback handler ("12")
    else if (/^\d+$/.test(rawTimeStr)) {
        startTime = `${rawTimeStr.padStart(2, '0')}:00`;
        const endTimeHours = String(parseInt(rawTimeStr, 10) + 1).padStart(2, '0');
        endTime = `${endTimeHours}:00`;
    }
}

// x represents the raw original IST Date string from WhatsApp
let x = dateFromWhatsApp.split('+')[0];

// 🚀 Execute the functional date transformations safely, capturing BOTH date and time
const { utcDate, utcTime } = convertISTtoUTC(x, startTime);

// Calculate End Time securely using the actual UTC date object
const startDateUTC = new Date(`${utcDate}T${utcTime}Z`);
const endDateUTC = new Date(startDateUTC.getTime() + 60 * 60 * 1000); // Add 1 Hour
const endUtcTime = endDateUTC.toISOString().substring(11, 19);

// Construct the final payload for Supabase insertion
const appointmentRecord = {
    patient_name: $('Get booking details from beforepaymentbookingdetails').first().json.profile_name,
    patient_email: appointmentData.patient_email,
    patient_contact: appointmentData.patient_contact,
    doctor: '',

    // 🚀 USE newly shifted UTC parameters here to permanently fix midnight sync errors
    appointment_date: utcDate, 
    date: dateFromWhatsApp, // Keeping original WhatsApp string for reference if needed

    start_time: utcTime,
    end_time: endUtcTime,
    time: utcTime,

    status: appointmentData.status,
    booking_reference: bookingref,
    payment_id: appointmentData.booking_reference,
    amount: appointmentData.amount,
    payment_method: appointmentData.payment_method,
    booking_type: $('Get business_type').first().json.business_type + " booking",
    description: appointmentData.description,
    tenant_id: $('Get booking details from beforepaymentbookingdetails').first().json.tenantid
};

return appointmentRecord;

